(1745981, 237033, 43565, '<td valign="top">I would like this better without the reflections on the bottle and the brown streaks from the drops.</td>', 'I would like this better without the reflections on the bottle and the brown streaks from the drops.', '2005-09-28 16:48:46.000000', NULL, 1),
(1745994, 237331, 43565, '<td valign="top">The objects are moving so fast I can''t tell what they are.</td>', 'The objects are moving so fast I can''t tell what they are.', '2005-09-28 16:51:20.000000', NULL, 1),
(1746001, 235320, 2978, '<td valign="top">It looks great and stylish. I''d present the bottle with the Beverage. To consider it as an advert. the red logo could be sharper.</td>', 'It looks great and stylish. I''d present the bottle with the Beverage. To consider it as an advert. the red logo could be sharper.', '2005-09-28 16:53:27.000000', NULL, 1),
(1746003, 237036, 20941, '<td valign="top">I would think about using a clear glass/cup so the orange juice looks yellow instead of green. You have a good looking subject with your OJ so maybe more of his face and less of his shirt would be more complimentary to your photo, although your composition is pretty good. There is potential here, just a little more work and attention to focus and you are on your way! Good Luck!</td>', 'I would think about using a clear glass/cup so the orange juice looks yellow instead of green. You have a good looking subject with your OJ so maybe more of his face and less of his shirt would be more complimentary to your photo, although your composition is pretty good. There is potential here, just a little more work and attention to focus and you are on your way! Good Luck!', '2005-09-28 16:53:47.000000', NULL, 1),
(1746014, 237024, 2978, '<td valign="top">What a lush! ;)</td>', 'What a lush! ;)', '2005-09-28 16:55:54.000000', NULL, 1),
(1746015, 235545, 2978, '<td valign="top">Nice clean shot of the product. Well done</td>', 'Nice clean shot of the product. Well done', '2005-09-28 16:56:34.000000', NULL, 1),
(1746032, 236978, 42984, '<td valign="top">Evocative and certainly a creative approach to trying something different</td>', 'Evocative and certainly a creative approach to trying something different', '2005-09-28 17:00:04.000000', NULL, 1),
(1746034, 235689, 20941, '<td valign="top">really too small to see, but looks like it would be interesting!</td>', 'really too small to see, but looks like it would be interesting!', '2005-09-28 17:00:45.000000', NULL, 1),
(1746036, 237337, 2978, '<td valign="top">Great shot. The splash is well captured. It''s rare to see this product in another angle.</td>', 'Great shot. The splash is well captured. It''s rare to see this product in another angle.', '2005-09-28 17:00:57.000000', NULL, 1),
(1746041, 235607, 43434, '<td valign="top">I can''t see how this is a beverage .. sorry.</td>', 'I can''t see how this is a beverage .. sorry.', '2005-09-28 17:03:21.000000', NULL, 1),
(1746045, 235280, 42984, '<td valign="top">Very good colour balance and lighting, I suspect it would score even higher with the subject a little further right - on the thirds line.  Right now it looks a little too centred</td>', 'Very good colour balance and lighting, I suspect it would score even higher with the subject a little further right - on the thirds line.  Right now it looks a little too centred', '2005-09-28 17:03:52.000000', NULL, 1),
(1746048, 236562, 43434, '<td valign="top">What has a skyscraper got to do with Beverage?</td>', 'What has a skyscraper got to do with Beverage?', '2005-09-28 17:04:25.000000', NULL, 1),
(1746055, 235410, 42984, '<td valign="top">The condensation on the bottle makes it look way out of focus, not sure the face adds anything</td>', 'The condensation on the bottle makes it look way out of focus, not sure the face adds anything', '2005-09-28 17:07:15.000000', NULL, 1),
(1746067, 237239, 42984, '<td valign="top">De-centering will add even more drama to this</td>', 'De-centering will add even more drama to this', '2005-09-28 17:10:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1746083, 236028, 42984, '<td valign="top">So moody, the wait for the sun in the right place was worth it.  The dirty glass bugs me because it doesn''t look like it''s just been drunk from, looks like the splashes of pouring.</td>', 'So moody, the wait for the sun in the right place was worth it.  The dirty glass bugs me because it doesn''t look like it''s just been drunk from, looks like the splashes of pouring.', '2005-09-28 17:16:51.000000', NULL, 1),
(1746091, 236694, 42984, '<td valign="top">Terrific setup with under-lit bottles like that. Focus and composition are an issue for me.</td>', 'Terrific setup with under-lit bottles like that. Focus and composition are an issue for me.', '2005-09-28 17:18:44.000000', NULL, 1),
(1746113, 235557, 37909, '<td valign="top">bailey''s is very photogenic!  nice composition and lighting.</td>', 'bailey''s is very photogenic!  nice composition and lighting.', '2005-09-28 17:28:10.000000', NULL, 1),
(1746114, 236050, 37909, '<td valign="top">awesome focus and dof!  cool effect. composition is great!</td>', 'awesome focus and dof!  cool effect. composition is great!', '2005-09-28 17:28:35.000000', NULL, 1),
(1746115, 237043, 37909, '<td valign="top">needs post processing</td>', 'needs post processing', '2005-09-28 17:28:50.000000', NULL, 1),
(1746119, 236703, 44980, '<td valign="top">good composition, good selection of colours. Shame about the little droplets on the glass on the left though.</td>', 'good composition, good selection of colours. Shame about the little droplets on the glass on the left though.', '2005-09-28 17:30:12.000000', NULL, 1),
(1746120, 236904, 44980, '<td valign="top">excellent contrast, sharp where it should be.</td>', 'excellent contrast, sharp where it should be.', '2005-09-28 17:30:44.000000', NULL, 1),
(1746130, 237043, 32084, '<td valign="top">Tough lighting and metering to get right on one of these shots.  Did you play around with levels in post at all?</td>', 'Tough lighting and metering to get right on one of these shots.  Did you play around with levels in post at all?', '2005-09-28 17:35:53.000000', NULL, 1),
(1746134, 236028, 14620, '<td valign="top">Very pretty.  Like the scene you''ve set.  I would''ve liked to have seen it without all the little drops inside the glass though,  just a little detail but an important one, I think anyways.   Nice job.</td>', 'Very pretty.  Like the scene you''ve set.  I would''ve liked to have seen it without all the little drops inside the glass though,  just a little detail but an important one, I think anyways.   Nice job.', '2005-09-28 17:37:18.000000', NULL, 1),
(1746135, 237317, 44980, '<td valign="top">The use of flash produced unwanted reflections and shadows. Focusing doesn''t seem to be that sharp. Sorry.</td>', 'The use of flash produced unwanted reflections and shadows. Focusing doesn''t seem to be that sharp. Sorry.', '2005-09-28 17:37:33.000000', NULL, 1),
(1746138, 237149, 44980, '<td valign="top">Brilliant colours love it</td>', 'Brilliant colours love it', '2005-09-28 17:38:34.000000', NULL, 1),
(1746142, 235445, 44980, '<td valign="top">Very cool, shame about the spilled liquid on the surface. Love the idea though and it''s pin sharp.</td>', 'Very cool, shame about the spilled liquid on the surface. Love the idea though and it''s pin sharp.', '2005-09-28 17:40:07.000000', NULL, 1),
(1746155, 235253, 32084, '<td valign="top">I really like this.  the only distracting element is the break in the backdrop and its slight dipping to the left.</td>', 'I really like this.  the only distracting element is the break in the backdrop and its slight dipping to the left.', '2005-09-28 17:46:35.000000', NULL, 1),
(1746161, 235705, 32084, '<td valign="top">Neat idea.  I like this, it is just that it took a while to find the key element that was indicated by the title.  It is kind of lost in the reflections and color of the fluid.</td>', 'Neat idea.  I like this, it is just that it took a while to find the key element that was indicated by the title.  It is kind of lost in the reflections and color of the fluid.', '2005-09-28 17:49:35.000000', NULL, 1),
(1746163, 237273, 32084, '<td valign="top">Very neat.  there are some halos around some of the bubbles and I wonder if maybe it was just a little over sharpened.  Very nice, regardless.</td>', 'Very neat.  there are some halos around some of the bubbles and I wonder if maybe it was just a little over sharpened.  Very nice, regardless.', '2005-09-28 17:50:43.000000', NULL, 1),
(1746170, 237159, 32084, '<td valign="top">I like the idea very much.  I think if the background were further back you might have been able to soften it and avoid the imprefections from coming through.  Also a little tighter focus on the glass itself might be nice.</td>', 'I like the idea very much.  I think if the background were further back you might have been able to soften it and avoid the imprefections from coming through.  Also a little tighter focus on the glass itself might be nice.', '2005-09-28 17:53:44.000000', NULL, 1),
(1746177, 235853, 27073, '<td valign="top">Nice job.</td>', 'Nice job.', '2005-09-28 17:55:51.000000', NULL, 1),
(1746180, 236187, 32084, '<td valign="top">Great background and presentation.  These are very tough to pull off.  I think the reflections on the glass distract and a crystal clear shot is needed to match your wonderful backdrop, lemon and mint leaf.</td>', 'Great background and presentation.  These are very tough to pull off.  I think the reflections on the glass distract and a crystal clear shot is needed to match your wonderful backdrop, lemon and mint leaf.', '2005-09-28 17:57:28.000000', NULL, 1),
(1746187, 237388, 32084, '<td valign="top">I must have tried a million of these as well.  Nice job.  a little more light on the fluid coming into the glass might have been awesome, but I''m sure you tried that.</td>', 'I must have tried a million of these as well.  Nice job.  a little more light on the fluid coming into the glass might have been awesome, but I''m sure you tried that.', '2005-09-28 17:59:36.000000', NULL, 1),
(1746190, 236762, 32084, '<td valign="top">Nice idea.  Backlighting might have helped get rid of that tough glare right in front.</td>', 'Nice idea.  Backlighting might have helped get rid of that tough glare right in front.', '2005-09-28 18:00:35.000000', NULL, 1),
(1746192, 235030, 43822, '<td valign="top">What The Hell Is This???<br/>This Looks Like A 2nd Grader Took The Picture With A Cheap Dollar Store Camera</td>', 'What The Hell Is This???This Looks Like A 2nd Grader Took The Picture With A Cheap Dollar Store Camera', '2005-09-28 18:01:40.000000', NULL, 1),
(1746201, 237298, 32084, '<td valign="top">I am guessing you were going for a high-key shot here.  It is too hot in many places in my opinion.  I reward the shot however for trying something different.</td>', 'I am guessing you were going for a high-key shot here.  It is too hot in many places in my opinion.  I reward the shot however for trying something different.', '2005-09-28 18:04:56.000000', NULL, 1),
(1746207, 237033, 32084, '<td valign="top">Great idea.  The reflections however lend me to belive you did this in the shower.  These are very tough to pull off, I truly understand that.</td>', 'Great idea.  The reflections however lend me to belive you did this in the shower.  These are very tough to pull off, I truly understand that.', '2005-09-28 18:06:32.000000', NULL, 1),
