(1747140, 237400, 41800, '<td valign="top">very nice lighting</td>', 'very nice lighting', '2005-09-29 00:11:04.000000', NULL, 1),
(1747142, 235908, 41106, '<td valign="top">Exquisite vessels.  Excellent detail, suitable to quality of subject.  Blackout of background enhances.  VERY nice job.</td>', 'Exquisite vessels.  Excellent detail, suitable to quality of subject.  Blackout of background enhances.  VERY nice job.', '2005-09-29 00:11:58.000000', NULL, 1),
