(1747785, 236541, 41675, '<td valign="top">I really like the idea of the large cup and marshmallows with the little one and mini marshmallows. I find the background a bit too busy and detracts my eyes from the cups themselves. Creative and clever.</td>', 'I really like the idea of the large cup and marshmallows with the little one and mini marshmallows. I find the background a bit too busy and detracts my eyes from the cups themselves. Creative and clever.', '2005-09-29 10:08:24.000000', NULL, 1),
(1747786, 235966, 41675, '<td valign="top">Very nice still life. I like the lighting alot. Was it all natural? I also like the dark green foliage in the background. For me, that provides a nice contrasting balance to the lighter tones of the rest of the photo. Good luck in the challenge. 8</td>', 'Very nice still life. I like the lighting alot. Was it all natural? I also like the dark green foliage in the background. For me, that provides a nice contrasting balance to the lighter tones of the rest of the photo. Good luck in the challenge. 8', '2005-09-29 10:09:20.000000', NULL, 1),
