INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1748301, 237092, 27482, '<td valign="top">I bet some people are putting a question mark as to wether this is fitting with the challenge, I totally understand them but I voted as if it fit the challenge although I think this is in a grey area.  Anyway, I don´t want to sound like a pyromaniac but I LOVE the flames, it´s got a great colour and texture too it and looks very cool and also fitting to have the people in the backround slightly out of focus.  However, I strongly dislike just seeing the back of the head of the firebreather so I only gave this a 6.</td>', 'I bet some people are putting a question mark as to wether this is fitting with the challenge, I totally understand them but I voted as if it fit the challenge although I think this is in a grey area.  Anyway, I don´t want to sound like a pyromaniac but I LOVE the flames, it´s got a great colour and texture too it and looks very cool and also fitting to have the people in the backround slightly out of focus.  However, I strongly dislike just seeing the back of the head of the firebreather so I only gave this a 6.', '2005-09-29 14:21:39.000000', NULL, 1),
(1748308, 235752, 40371, '<td valign="top">The background is too plain for such a bright subject, otherwise this would be a 9 in my book.  Nice capture on the flying liquid.</td>', 'The background is too plain for such a bright subject, otherwise this would be a 9 in my book.  Nice capture on the flying liquid.', '2005-09-29 14:23:20.000000', NULL, 1),
(1748325, 235083, 32033, '<td valign="top">Swtich the numbers around and you have the year I was born</td>', 'Swtich the numbers around and you have the year I was born', '2005-09-29 14:27:29.000000', NULL, 1),
(1748331, 236775, 27482, '<td valign="top">Too bad the shot looks badly pixelated, I really like the composition and the single colour.  5 from me...</td>', 'Too bad the shot looks badly pixelated, I really like the composition and the single colour.  5 from me...', '2005-09-29 14:29:28.000000', NULL, 1),
(1748349, 237273, 27482, '<td valign="top">This shot is very odd looking and you know what, I like it.  I still have some reserve about the monotone red, I think that I personally would have liked this shot better if there were some other colour in the shot contrasting the red but well it works pretty well as it is.  Perhaps some, I dunno, green liquid within the glass itself?  Just a thought...  Anyway, nice work, gave it an 8.</td>', 'This shot is very odd looking and you know what, I like it.  I still have some reserve about the monotone red, I think that I personally would have liked this shot better if there were some other colour in the shot contrasting the red but well it works pretty well as it is.  Perhaps some, I dunno, green liquid within the glass itself?  Just a thought...  Anyway, nice work, gave it an 8.', '2005-09-29 14:33:13.000000', NULL, 1),
(1748352, 236562, 32033, '<td valign="top">how does it taste?</td>', 'how does it taste?', '2005-09-29 14:34:07.000000', NULL, 1),
(1748360, 237416, 27482, '<td valign="top">Nice shot, looks like a good place to take a coffee break, where is this taken, I get a very "australian" feel from this picture even though I have never been there.  Anyway, I still would have liked this shot a whole lot better if it weren´t for the green hue cast and maybe a wider shot with the rest of the truck all in the frame...</td>', 'Nice shot, looks like a good place to take a coffee break, where is this taken, I get a very "australian" feel from this picture even though I have never been there.  Anyway, I still would have liked this shot a whole lot better if it weren´t for the green hue cast and maybe a wider shot with the rest of the truck all in the frame...', '2005-09-29 14:36:30.000000', NULL, 1),
(1748363, 237337, 32033, '<td valign="top">like the splash</td>', 'like the splash', '2005-09-29 14:37:38.000000', NULL, 1),
(1748366, 235853, 32033, '<td valign="top">nice frame</td>', 'nice frame', '2005-09-29 14:38:28.000000', NULL, 1),
(1748374, 237416, 43115, '<td valign="top">The greenish color cast makes this photo very hard to look at.  It''s awfuly busy and doesn''t really tell a story.  The countryside looks very pretty, perhaps if you had posed the guy in the bed of the truck with the mountains behind him, or something like that...</td>', 'The greenish color cast makes this photo very hard to look at.  It''s awfuly busy and doesn''t really tell a story.  The countryside looks very pretty, perhaps if you had posed the guy in the bed of the truck with the mountains behind him, or something like that...', '2005-09-29 14:41:02.000000', NULL, 1),
(1748389, 236703, 40371, '<td valign="top">I really like the colors in this picture but I think it would look a lot better if the 3 standing glasses weren''t cropped off and instead had a little space between the rim of the glasses and the top of the picture.</td>', 'I really like the colors in this picture but I think it would look a lot better if the 3 standing glasses weren''t cropped off and instead had a little space between the rim of the glasses and the top of the picture.', '2005-09-29 14:49:56.000000', NULL, 1),
(1748400, 235731, 327, '<td valign="top">Clever.</td>', 'Clever.', '2005-09-29 14:52:14.000000', NULL, 1),
(1748406, 235517, 43565, '<td valign="top">His skin is very red, at least on my monitor, and there is too much light on his eye area.  I would also like it more without the brown and blue next to his hand.</td>', 'His skin is very red, at least on my monitor, and there is too much light on his eye area.  I would also like it more without the brown and blue next to his hand.', '2005-09-29 14:54:58.000000', NULL, 1),
(1748407, 237390, 32033, '<td valign="top">Not sure what this is</td>', 'Not sure what this is', '2005-09-29 14:55:25.000000', NULL, 1),
(1748408, 237092, 43565, '<td valign="top">I like the fire, but I am not sure what the beverage is.</td>', 'I like the fire, but I am not sure what the beverage is.', '2005-09-29 14:55:49.000000', NULL, 1),
