(1749595, 236171, 41106, '<td valign="top">Ah.......an Australian treasure.  I find it interesting that your title is punctuated with an exclamation rather than a question.  This makes sense, since the bottle appears empty of this delectable beverage.  An exaggerated demand for more makes good sense.  Oh, yea...and I did notice the reflection in the bottle.  Very nice.  Is the subject named "Jacob?"</td>', 'Ah.......an Australian treasure.  I find it interesting that your title is punctuated with an exclamation rather than a question.  This makes sense, since the bottle appears empty of this delectable beverage.  An exaggerated demand for more makes good sense.  Oh, yea...and I did notice the reflection in the bottle.  Very nice.  Is the subject named "Jacob?"', '2005-09-30 00:15:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1749600, 237348, 41675, '<td valign="top">Nice composition and colors. I don''t drink, but that liquid looks almost good enough to try a sip...almost. :-) 10</td>', 'Nice composition and colors. I don''t drink, but that liquid looks almost good enough to try a sip...almost. :-) 10', '2005-09-30 00:16:18.000000', NULL, 1),
(1749604, 236888, 41675, '<td valign="top">Somebody had some fun! A busy composition, but I like the myriad of colors and light reflections.</td>', 'Somebody had some fun! A busy composition, but I like the myriad of colors and light reflections.', '2005-09-30 00:16:59.000000', NULL, 1),
(1749607, 235814, 41675, '<td valign="top">I like the setup. Had the glass on the left been moved closer to the right and your subjects formed a  more visual triangle, I would have scored it higher. My favorite part is the plate, salt and limes. I like the chosen color scheme.</td>', 'I like the setup. Had the glass on the left been moved closer to the right and your subjects formed a  more visual triangle, I would have scored it higher. My favorite part is the plate, salt and limes. I like the chosen color scheme.', '2005-09-30 00:18:38.000000', NULL, 1),
(1749609, 237416, 41675, '<td valign="top">For me, I like photos where the main subject isn''t in the center of a photo - just seems to add a bit more interest when they are more off to one side or the other. Judging by the background landscape, looks like a beautiful place.</td>', 'For me, I like photos where the main subject isn''t in the center of a photo - just seems to add a bit more interest when they are more off to one side or the other. Judging by the background landscape, looks like a beautiful place.', '2005-09-30 00:20:08.000000', NULL, 1),
(1749610, 235720, 41675, '<td valign="top">If someone were to show me this photo and say guess the topic, it would take me a while (if ever) to guess it was beverage. That aside, I find this a very intriguing photo and I wonder what message you''re trying to get across to the viewer.</td>', 'If someone were to show me this photo and say guess the topic, it would take me a while (if ever) to guess it was beverage. That aside, I find this a very intriguing photo and I wonder what message you''re trying to get across to the viewer.', '2005-09-30 00:21:37.000000', NULL, 1),
(1749614, 235815, 41675, '<td valign="top">There is a beverage, but compared to other entries, I don''t find the subject interesting. The most interesting part to me is the blue edge of the liquid.</td>', 'There is a beverage, but compared to other entries, I don''t find the subject interesting. The most interesting part to me is the blue edge of the liquid.', '2005-09-30 00:22:42.000000', NULL, 1),
