(1751688, 237141, 41675, '<td valign="top">Wow, that is one very strong red color - almost makes me wish I was color blind <br/>:-) Good ad for Bud.</td>', 'Wow, that is one very strong red color - almost makes me wish I was color blind :-) Good ad for Bud.', '2005-10-01 02:09:31.000000', NULL, 1),
(1751689, 236562, 24363, '<td valign="top">beverages?</td>', 'beverages?', '2005-10-01 02:09:50.000000', NULL, 1),
(1751690, 236974, 41675, '<td valign="top">lol - funny title. I like the green of the cap, but the background is just a little bit too harshly white for me.</td>', 'lol - funny title. I like the green of the cap, but the background is just a little bit too harshly white for me.', '2005-10-01 02:10:14.000000', NULL, 1),
(1751692, 236025, 41675, '<td valign="top">Hmmmm, now that looks good (what''s on the grill, not the beer) :-) Nice setup. and good flame catch. I like how the color of the flames and that of the glass are similar - helps tie it in together for me. 10</td>', 'Hmmmm, now that looks good (what''s on the grill, not the beer) :-) Nice setup. and good flame catch. I like how the color of the flames and that of the glass are similar - helps tie it in together for me. 10', '2005-10-01 02:11:41.000000', NULL, 1),
(1751694, 237096, 41675, '<td valign="top">I like the setup, but I find the red too saturated for my tastes. I think a bit more focus would have also helped.</td>', 'I like the setup, but I find the red too saturated for my tastes. I think a bit more focus would have also helped.', '2005-10-01 02:12:27.000000', NULL, 1),
(1751695, 235746, 41675, '<td valign="top">The highlights of the sun in the water are a bit harsh for me, but I like the glass setup itself and I think having the person in the water adds interest to the photo. Like the glass is waiting for him when he (or she) returns.</td>', 'The highlights of the sun in the water are a bit harsh for me, but I like the glass setup itself and I think having the person in the water adds interest to the photo. Like the glass is waiting for him when he (or she) returns.', '2005-10-01 02:13:42.000000', NULL, 1),
(1751696, 237318, 41675, '<td valign="top">I wish there was a bit more of the beverage or that the shot was pulled back a little more as the limes look so crowded. I like the colors and especially the small bubble area in the lower middle area.</td>', 'I wish there was a bit more of the beverage or that the shot was pulled back a little more as the limes look so crowded. I like the colors and especially the small bubble area in the lower middle area.', '2005-10-01 02:14:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1751697, 237367, 41675, '<td valign="top">For me, that''s a very sensual title...and image.</td>', 'For me, that''s a very sensual title...and image.', '2005-10-01 02:15:29.000000', NULL, 1),
(1751698, 235888, 41675, '<td valign="top">I like the hands and the glass, but something about the body on the lower right side seems very...odd. The yellow overtones and grain, I think.</td>', 'I like the hands and the glass, but something about the body on the lower right side seems very...odd. The yellow overtones and grain, I think.', '2005-10-01 02:16:17.000000', NULL, 1),
(1751699, 236990, 41675, '<td valign="top">With a bit more definition on the necks of the bottles, they tops wouldn''t seem to be "floating" for me.</td>', 'With a bit more definition on the necks of the bottles, they tops wouldn''t seem to be "floating" for me.', '2005-10-01 02:17:13.000000', NULL, 1),
(1751700, 237363, 41675, '<td valign="top">While she looks like she''s having fun, I''m not crazy about the yellow background as I think it tends to make her skin look more yellow and sallow.</td>', 'While she looks like she''s having fun, I''m not crazy about the yellow background as I think it tends to make her skin look more yellow and sallow.', '2005-10-01 02:18:05.000000', NULL, 1),
(1751701, 237146, 41675, '<td valign="top">I like it. Nothing quite like fresh water. Good composition and I like the water droplets coming from his hand. 7</td>', 'I like it. Nothing quite like fresh water. Good composition and I like the water droplets coming from his hand. 7', '2005-10-01 02:18:41.000000', NULL, 1),
(1751703, 237347, 41675, '<td valign="top">For me, this photo would have more interest if your main subject wasn''t so centered. My favorite part is the line on the glass itself.</td>', 'For me, this photo would have more interest if your main subject wasn''t so centered. My favorite part is the line on the glass itself.', '2005-10-01 02:19:41.000000', NULL, 1),
(1751705, 236694, 41675, '<td valign="top">I wish there was a bit more overall focus as I really like the lighting and angle.</td>', 'I wish there was a bit more overall focus as I really like the lighting and angle.', '2005-10-01 02:20:14.000000', NULL, 1),
(1751706, 237210, 41675, '<td valign="top">It took me a few seconds to figure out what the object was, then it dawned on me. Interesting take on the beverage challenge. The white highlights are a little overdone to me, but I like the use of black and white.</td>', 'It took me a few seconds to figure out what the object was, then it dawned on me. Interesting take on the beverage challenge. The white highlights are a little overdone to me, but I like the use of black and white.', '2005-10-01 02:21:30.000000', NULL, 1),
(1751736, 237154, 40081, '<td valign="top">Quite original.</td>', 'Quite original.', '2005-10-01 03:15:01.000000', NULL, 1),
(1751737, 235058, 40081, '<td valign="top">I miss the real beverage in this picture. The yellowish cast is pleasing.</td>', 'I miss the real beverage in this picture. The yellowish cast is pleasing.', '2005-10-01 03:16:14.000000', NULL, 1),
(1751738, 235731, 40081, '<td valign="top">Original. Nice DOF and composition.</td>', 'Original. Nice DOF and composition.', '2005-10-01 03:17:27.000000', NULL, 1),
(1751740, 237281, 40081, '<td valign="top">This is nice. A pity the twig is in the foreground</td>', 'This is nice. A pity the twig is in the foreground', '2005-10-01 03:29:21.000000', NULL, 1),
(1751741, 237337, 40081, '<td valign="top">Great action, composition and colors</td>', 'Great action, composition and colors', '2005-10-01 03:30:28.000000', NULL, 1),
(1751742, 235356, 40081, '<td valign="top">A pity the bubbles are not more predominant. I almost did not see them. Apart from that, really nice</td>', 'A pity the bubbles are not more predominant. I almost did not see them. Apart from that, really nice', '2005-10-01 03:31:43.000000', NULL, 1),
(1751743, 236507, 40081, '<td valign="top">Not very clear what this is about</td>', 'Not very clear what this is about', '2005-10-01 03:34:08.000000', NULL, 1),
(1751745, 236890, 40081, '<td valign="top">Wonderful texture, colors and lighting - your subject is a good suggestion for the score - (V)8</td>', 'Wonderful texture, colors and lighting - your subject is a good suggestion for the score - (V)8', '2005-10-01 03:35:51.000000', NULL, 1),
(1751746, 236920, 40081, '<td valign="top">Great. A pity that the bottle looks unsharp - 9</td>', 'Great. A pity that the bottle looks unsharp - 9', '2005-10-01 03:37:00.000000', NULL, 1),
(1751750, 236061, 21216, '<td valign="top">Great image, I love it, it really makes me incredibly thirsty. I like the lighting as well the only thing that you could have done better would be to avoid cutting the top of the glass.<br/> <br/>I hope your drank this after ;)</td>', 'Great image, I love it, it really makes me incredibly thirsty. I like the lighting as well the only thing that you could have done better would be to avoid cutting the top of the glass. I hope your drank this after ;)', '2005-10-01 03:41:14.000000', NULL, 1),
(1751752, 237325, 40081, '<td valign="top">What a beautiful picture: composition, retrofeel, use of color and the smoke (where have I seen a smoke machine before, mmmm ... it will come to me eventually) - 9</td>', 'What a beautiful picture: composition, retrofeel, use of color and the smoke (where have I seen a smoke machine before, mmmm ... it will come to me eventually) - 9', '2005-10-01 03:46:06.000000', NULL, 1),
(1751754, 237096, 19040, '<td valign="top">I like the colors and composition. Nice job.</td>', 'I like the colors and composition. Nice job.', '2005-10-01 03:48:35.000000', NULL, 1),
(1751756, 237406, 19040, '<td valign="top">I like the way this glows.</td>', 'I like the way this glows.', '2005-10-01 03:49:52.000000', NULL, 1),
(1751759, 235389, 40081, '<td valign="top">I like the idea but find the lighting a bit too harsh for my taste</td>', 'I like the idea but find the lighting a bit too harsh for my taste', '2005-10-01 03:57:23.000000', NULL, 1),
(1751761, 236990, 40081, '<td valign="top">Beautiful colors. I would have straightened the image and put put the bottles on the right instead of the left of the picture. Overall very nice picture.</td>', 'Beautiful colors. I would have straightened the image and put put the bottles on the right instead of the left of the picture. Overall very nice picture.', '2005-10-01 04:07:10.000000', NULL, 1),
(1751772, 236682, 26849, '<td valign="top">Love the composition.</td>', 'Love the composition.', '2005-10-01 04:27:45.000000', NULL, 1),
(1751794, 235689, 24983, '<td valign="top">An original thought well photographed 10</td>', 'An original thought well photographed 10', '2005-10-01 05:42:36.000000', NULL, 1),
(1751795, 236050, 24983, '<td valign="top">I like your idea and the way you photographed it 10</td>', 'I like your idea and the way you photographed it 10', '2005-10-01 05:43:33.000000', NULL, 1),
(1751796, 235746, 24983, '<td valign="top">the use of the perspective and light made this a stand out image for me 10</td>', 'the use of the perspective and light made this a stand out image for me 10', '2005-10-01 05:46:02.000000', NULL, 1),
(1751797, 237363, 40081, '<td valign="top">This is a nice and cheerful picture. The shadow of the glass is nice but at the same time there is the distracting shadow of the model.</td>', 'This is a nice and cheerful picture. The shadow of the glass is nice but at the same time there is the distracting shadow of the model.', '2005-10-01 05:46:52.000000', NULL, 1),
