(1751799, 236175, 24983, '<td valign="top">this really stands out and hits you in the eye  10</td>', 'this really stands out and hits you in the eye  10', '2005-10-01 05:48:34.000000', NULL, 1),
(1751800, 235860, 40081, '<td valign="top">Would be better without the half-person in the background and with the rule of 1/3 applied for the bottle</td>', 'Would be better without the half-person in the background and with the rule of 1/3 applied for the bottle', '2005-10-01 05:48:44.000000', NULL, 1),
