(1752720, 236887, 40667, '<td valign="top">I love it! wonderfull job! the lighting seems perfact due to the fact that no harsh light has found its way to the glass!! great job!</td>', 'I love it! wonderfull job! the lighting seems perfact due to the fact that no harsh light has found its way to the glass!! great job!', '2005-10-01 18:51:07.000000', NULL, 1),
