INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1752724, 235557, 40667, '<td valign="top">Great job! the shaddows at the bottom of the photo aren''t that flattering, but when working with natural light, its hard to componsate! next time maybe try using a gold reflector to bounc a bit of soft light back into the bottle! good job!</td>', 'Great job! the shaddows at the bottom of the photo aren''t that flattering, but when working with natural light, its hard to componsate! next time maybe try using a gold reflector to bounc a bit of soft light back into the bottle! good job!', '2005-10-01 18:52:49.000000', NULL, 1),
