(1762753, 237273, 37779, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mpemberton:</b></div><hr/><i> Theres wine in Utah?  ;-)<br/></i></td></tr></table> <br/> <br/>My mistake! "Grape Juice" glass ;-)</td>', 'Originally posted by mpemberton: Theres wine in Utah?  ;-)  My mistake! "Grape Juice" glass ;-)', '2005-10-05 20:25:11.000000', NULL, 0),
