(1762800, 235731, 37544, '<td valign="top">you are a genius!</td>', 'you are a genius!', '2005-10-05 20:44:43.000000', NULL, 0),
(1762896, 235853, 5515, '<td valign="top">Great image and my favorite vodka...</td>', 'Great image and my favorite vodka...', '2005-10-05 21:26:55.000000', NULL, 0),
(1762981, 237288, 22379, '<td valign="top">i disagree with the "too dark"s if your monitor is calibrated its not too dark for the mood you were trying to achieve (which doesn''t do too well on DPC, just so you know, not so you should change). However, the image has very little interest to it and the hhighlights under the can are blown. <br/>Everyonehas to start somewhere. Welcome to DPC.</td>', 'i disagree with the "too dark"s if your monitor is calibrated its not too dark for the mood you were trying to achieve (which doesn''t do too well on DPC, just so you know, not so you should change). However, the image has very little interest to it and the hhighlights under the can are blown. Everyonehas to start somewhere. Welcome to DPC.', '2005-10-05 21:52:44.000000', NULL, 0),
(1763046, 235731, 22734, '<td valign="top">What an image. Very well done with humor and genius. Congratulations on your BLUE!</td>', 'What an image. Very well done with humor and genius. Congratulations on your BLUE!', '2005-10-05 22:10:11.000000', NULL, 0),
(1763054, 236920, 22734, '<td valign="top">Hey Antoine: my warmest congratulations on this slick and superb splash of an image. Keep up the faith and your good work. Happy RED!</td>', 'Hey Antoine: my warmest congratulations on this slick and superb splash of an image. Keep up the faith and your good work. Happy RED!', '2005-10-05 22:12:12.000000', NULL, 0),
(1763056, 235731, 45089, '<td valign="top">I love Pepsi! Nice color, it is very unique! love it want to vote for mine. Mine is Apples, you do not have to though.<br/>love yours!<br/> <br/></td>', 'I love Pepsi! Nice color, it is very unique! love it want to vote for mine. Mine is Apples, you do not have to though.love yours! ', '2005-10-05 22:12:55.000000', NULL, 0),
(1763060, 237273, 22734, '<td valign="top">Katherine straikes again and now hits the bulls eye. I am very happy for you and wish you more success. You do have the talent. Congratulations on your YELLOW!</td>', 'Katherine straikes again and now hits the bulls eye. I am very happy for you and wish you more success. You do have the talent. Congratulations on your YELLOW!', '2005-10-05 22:13:35.000000', NULL, 0),
(1763092, 237325, 22734, '<td valign="top">Wow! Cool drink, cool cooler and cool floor and not to mention the c...ice. Congratulations on your RED!<br/><br/><i>Message edited by author 2005-10-07 21:43:27.</i></td>', 'Wow! Cool drink, cool cooler and cool floor and not to mention the c...ice. Congratulations on your RED!', '2005-10-05 22:21:24.000000', '2005-10-07 22:43:27.000000', 0),
